#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);
vector<vector<long long>>t(n);
for(int i=0;i<n;++i){t[i].resize(i+1);
for(int j=0;j<=i;++j)scanf("%lld",&t[i][j]);}
vector<long long>dp=t[n-1];
for(int i=n-2;i>=0;--i)for(int j=0;j<=i;++j)
dp[j]=min(dp[j],dp[j+1])+t[i][j];
printf("%lld\n",dp[0]);return 0;}

